			long selective = fixture.term(new CountingIRI("urn:optional-probe:match", probes));
			ValuesRow[] rightRows = new ValuesRow[RIGHT_ROWS];
			long finalPayload = UNKNOWN;
			for (int index = 0; index < RIGHT_ROWS; index++) {
				long key = index == RIGHT_ROWS - 1 ? selective
						: fixture.term(vf.createIRI("urn:optional-probe:miss-" + index));
				long payload = fixture.term(vf.createLiteral("row-" + index + "-" + "x".repeat(512)));
				if (index == 0) {
					// The early shared column is bound on one row; every other RHS row leaves it unbound.
					rightRows[index] = new ValuesRow(new int[] { EARLY, SELECTIVE, PAYLOAD },
							new long[] { early, key, payload });
				} else {
					rightRows[index] = new ValuesRow(new int[] { SELECTIVE, PAYLOAD },
							new long[] { key, payload });
				}
				finalPayload = payload;
			}
			AtomicInteger rightCloses = new AtomicInteger();
			AtomicInteger leftCloses = new AtomicInteger();
			SlotPlan right = trackClose(SlotPlan.values(rightRows), rightCloses);
			ValuesRow repeatedLeft = new ValuesRow(new int[] { EARLY, SELECTIVE }, new long[] { early, selective });
			SlotPlan left = trackClose(SlotPlan.values(new ValuesRow[] {
					repeatedLeft, repeatedLeft, repeatedLeft, repeatedLeft }), leftCloses);
