	private static SlotPlan trackClose(SlotPlan plan, AtomicInteger closes) {
		return new SlotPlan() {
			@Override
			public RowCursor open(RowState row) throws IOException {
				RowCursor cursor = plan.open(row);
				return new RowCursor() {
					private boolean closed;

					@Override
					public boolean next() throws IOException {
						return cursor.next();
					}

					@Override
					public void close() {
						if (!closed) {
							closed = true;
							closes.incrementAndGet();
							cursor.close();
						}
					}
				};
			}

			@Override
			public long producedMask() {
				return plan.producedMask();
			}
		};
	}

	private static boolean hasOptionalSpill(Path path) throws IOException {
		return RecordingFile.readAllEvents(path)
				.stream()
				.anyMatch(event -> event.getEventType().getName().equals("org.eclipse.rdf4j.lmdb.NativeExecutionPhase")
						&& event.getString("phase").equals("spill")
						&& event.getStackTrace() != null
						&& event.getStackTrace()
								.getFrames()
								.stream()
								.anyMatch(frame -> optionalSpillOwner(frame.getMethod().getType().getName())));
	}

	private static boolean optionalSpillOwner(String className) {
		String indexClass = "org.eclipse.rdf4j.sail.lmdb.evaluation.OptionalCompatibilityIndex";
		return className.equals(NativeResultReplay.class.getName()) || className.equals(indexClass)
				|| className.startsWith(indexClass + "$");
	}

