	/** A valid RDF term whose equality override measures real compatibility comparisons, even if decoding is cached. */
	private static final class CountingIRI extends SimpleIRI {
		private static final long serialVersionUID = 1L;
		private final ProbeCounts probes;

		CountingIRI(String iri, ProbeCounts probes) {
			super(iri);
			this.probes = probes;
		}

		@Override
		public boolean equals(Object other) {
			if (probes.enabled) {
				probes.equalities++;
			}
			return super.equals(other);
		}
	}

